values.content:
=あなたは日本の中小企業の問い合わせメール対応アシスタントです。次のメールを読んで、(1)分類 と (2)一次返信の下書き を作ってください。

分類は必ず次の4つのどれか1つ: 見積依頼 / 技術的な質問 / 請求・支払い / 営業・その他。判断に迷ったら、必ず「営業・その他」に分類してください。

返信下書きは、相手への宛名、お問い合わせへのお礼、内容を確認して担当から折り返す旨、を入れた丁寧な日本語のビジネスメール本文にしてください。これは人間が確認・修正してから送る一次返信の下書きです。金額の提示や納期の確約はしないでください。

説明や前置きを一切付けず、厳密なJSONのみで返してください。例: {"category":"見積依頼","reply_draft":"株式会社サンプル 御中\n\nお問い合わせいただきありがとうございます。…"}

--- 対象メール ---
件名: {{ $json.Subject }}
差出人: {{ $json.From }}
本文:
{{ $json.text || $json.snippet || '' }}
--- ここまで ---

parameters.jsCode:
// Geminiの返答テキストを取り出す（ノード構成で入る場所が違うため複数候補を見る）
let raw = $json.content?.parts?.[0]?.text ?? $json.candidates?.[0]?.content?.parts?.[0]?.text ?? $json.text ?? $json.response ?? $json.output ?? '';
if (typeof raw !== 'string') raw = JSON.stringify(raw);
// ```json ... ``` のコードフェンスが付く場合があるので除去してから変換（動画Step6のコツ）
raw = raw.replace(/```json/gi, '').replace(/```/g, '').trim();
let p = {};
try {
  p = JSON.parse(raw);
} catch (e) {
  p = { category: '', reply_draft: '', _parse_error: String(e), _raw: raw };
}
// 分類名 → GmailラベルID の対応表。★動画Step3でGmailに作った4ラベルのIDに置換する。
// ラベルIDは Gmail API の labels 一覧や、n8nのGmailノードでラベルを選ぶ画面で確認できる（Label_xxxxxxxxxx 形式。システムラベル以外は名前でなくIDが必要）。
const LABELS = {
  '見積依頼': 'REPLACE_WITH_LABEL_ID_MITSUMORI',
  '技術的な質問': 'REPLACE_WITH_LABEL_ID_GIJUTSU',
  '請求・支払い': 'REPLACE_WITH_LABEL_ID_SEIKYU',
  '営業・その他': 'REPLACE_WITH_LABEL_ID_SONOTA'
};
// AIが4分類以外を返した／パースに失敗した場合も『営業・その他』へ倒す（人間が見る箱に集めるフォールバック）
const category = Object.prototype.hasOwnProperty.call(LABELS, p.category) ? p.category : '営業・その他';
return [{ json: {
  "分類": category,
  "ラベルID": LABELS[category],
  "返信下書き": p.reply_draft || ''
} }];
